function() {
  try {
    // One id per navigation, not per page load.
    //
    // Both copies of a page view have to carry the same id — the browser
    // Pixel fires one and the GA4 page_view carries the other to the server
    // container — so it is cached rather than generated twice. But it used to
    // be cached on `window` and never renewed, which is only harmless while
    // exactly one page view exists per load. The moment a single-page
    // navigation fires another, every one of them would arrive under the
    // first id and Meta would collapse them all into that first page view.
    //
    // Keyed on the URL, so going A -> B -> A gets a third id rather than
    // reusing A's: what is being identified is the navigation, not the page.
    var here = window.location.pathname + window.location.search;
    var cache = window.__ssPageView;
    if (!cache || cache.url !== here) {
      cache = {
        url: here,
        id: 'pageview_' + new Date().getTime() + '_' + Math.random().toString(36).slice(2, 10)
      };
      window.__ssPageView = cache;
    }
    return cache.id;
  } catch (e) {
    return undefined;
  }
}

function() {
  // Meta click-id for the server container. The CAPI tag on
  // ss.sleepsheetbd.com can't reliably read the site's _fbc cookie (the
  // app's own copy is host-only on sleepsheetbd.com), so it is sent as an
  // explicit `fbc` event parameter, which the stape tag auto-maps.
  try {
    var m = document.cookie.match(/(?:^|; )_fbc=([^;]*)/);
    if (m && m[1]) return decodeURIComponent(m[1]);
    // Fallback the app writes in lib/meta-fbc.ts when the cookie didn't stick.
    var stored = window.localStorage && window.localStorage.getItem('_fbc_captured');
    if (stored) return stored;
    var q = window.location.search.match(/[?&]fbclid=([^&#]+)/);
    if (q && q[1]) return 'fb.1.' + new Date().getTime() + '.' + decodeURIComponent(q[1]);
  } catch (e) {}
  return undefined;
}

function() {
  // Meta matches an event to a catalog product by content_ids. Without it,
  // content_type:'product' means nothing and no catalog/DPA audience can be
  // built. The ids here are ecommerce.items[].item_id, which the app sets to
  // the product id — the same value the feed in lib/meta-catalog uses as the
  // catalog item id, so the two sides line up.
  try {
    var items = {{dlv - ecommerce.items}};
    if (!items || !items.length) return '[]';
    var ids = [];
    for (var i = 0; i < items.length; i++) {
      var id = items[i] && (items[i].item_id || items[i].id);
      if (id) ids.push(String(id));
    }
    return JSON.stringify(ids);
  } catch (e) {
    return '[]';
  }
}

function() {
  // The per-item form: id + quantity + item_price. Meta uses it for value
  // optimisation and for the item breakdown on the event.
  try {
    var items = {{dlv - ecommerce.items}};
    if (!items || !items.length) return '[]';
    var out = [];
    for (var i = 0; i < items.length; i++) {
      var it = items[i];
      if (!it) continue;
      var id = it.item_id || it.id;
      if (!id) continue;
      out.push({
        id: String(id),
        quantity: Number(it.quantity) || 1,
        item_price: Number(it.price) || 0
      });
    }
    return JSON.stringify(out);
  } catch (e) {
    return '[]';
  }
}
